mapper.insert:
insert into user_account (
    id, tenant_id, app_id, email, display_name, status, register_source, deleted, version, created_at, updated_at
) values (
    #{id}, #{tenantId}, #{appId}, #{email}, #{displayName}, #{status}, #{registerSource}, false, 0, now(), now()
)

mapper.update:
update user_account
set last_login_at = now(),
    updated_at = now(),
    version = version + 1
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and id = #{userId}

update user_session
set revoked = true
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and revoked = false
  and expired_at > now()

mapper.insert:
insert into user_session (
    id, tenant_id, app_id, user_id, session_token_hash, refresh_token_hash, device_id, client_version, expired_at, revoked, created_at
) values (
    #{id}, #{tenantId}, #{appId}, #{userId}, #{sessionTokenHash}, #{refreshTokenHash}, #{deviceId}, #{clientVersion}, #{expiredAt}, false, now()
)

mapper.sql:
where u.tenant_id = #{tenantId}
  and u.app_id = #{appId}

  and u.deleted = false


  and u.status = #{status}


  and (
    lower(coalesce(u.email, '')) like concat('%', lower(#{keyword}), '%')
    or lower(coalesce(u.display_name, '')) like concat('%', lower(#{keyword}), '%')
    or lower(u.id) like concat('%', lower(#{keyword}), '%')
  )

mapper.select:
select

from user_account u


order by coalesce(u.last_login_at, u.created_at) desc, u.id desc
limit #{limit}
offset #{offset}

select

from user_account u

where u.tenant_id = #{tenantId}
  and u.app_id = #{appId}
  and u.id = #{userId}
limit 1
